# dmrobotics/__init__.py
from __future__ import annotations

from dataclasses import dataclass
from enum import Enum
from typing import Optional, Union, Tuple, Dict, Any, List

import numpy as np

from . import dmSDK as _cx

__all__ = [
    "Sensor",
    "SensorOptions",
    "Mode",
    "listConnectedDevIDs",
    "init_sensor_cache",
    "set_detect_enabled",
]


@dataclass(frozen=True)
class Mode(str, Enum):
    STANDARD = "standard"
    HIGH = "high"


@dataclass(frozen=False)
class SensorOptions:
    dev_id: Union[int, str]
    show_fps: bool = False
    mode: Mode = Mode.HIGH
    backend: str = "Flux"
    enable_raw: bool = True
    enable_deformation: bool = True
    enable_shear: bool = True
    enable_depth: bool = True
    enable_force: bool = True
    max_fps: int = 120
    remote_addr: str = "192.168.127.10:50051"
    pc_host: str = "0.0.0.0"
    pc_port: int = 60000



def _mk_cx_options(opt: SensorOptions) -> _cx.Options:
    cxopt = _cx.Options()
    cxopt.show_fps = bool(opt.show_fps)
    cxopt.dev_id = str(opt.dev_id)

    m = getattr(opt.mode, "value", opt.mode)
    m = str(m).strip().lower()
    cxopt.mode = _cx.Mode.High if m.startswith("h") else _cx.Mode.Standard

    cxopt.enable_raw = bool(opt.enable_raw)
    cxopt.enable_deformation = bool(opt.enable_deformation)
    cxopt.enable_shear = bool(opt.enable_shear)
    cxopt.enable_depth = bool(opt.enable_depth)
    cxopt.enable_force = bool(opt.enable_force)

    if hasattr(cxopt, "max_fps"):
        cxopt.max_fps = int(opt.max_fps)
    if hasattr(cxopt, "enable_udp"):
        cxopt.enable_udp = True
    if hasattr(cxopt, "udp_ip"):
        cxopt.udp_ip = str(opt.pc_host)
    if hasattr(cxopt, "udp_port"):
        cxopt.udp_port = int(opt.pc_port)

    return cxopt


class Sensor:
    def __init__(self, opt: SensorOptions) -> None:
        self._opt = opt
        self._dev = _cx.Sensor(_mk_cx_options(opt))
        self._event_seq: int = 0
        self._enable_raw = bool(opt.enable_raw)
        self._enable_deformation = bool(opt.enable_deformation)
        self._enable_depth = bool(opt.enable_depth)
        self._enable_shear = bool(opt.enable_shear)
        self._enable_force = bool(opt.enable_force)

    def getBaseFrame(self) -> Tuple[int, Optional[_cx.DMTacImage]]:
        fid, dmimg = self._dev.getBaseImage()
        return int(fid), dmimg

    def getRawImg(self) -> Tuple[int, Optional[_cx.DMTacImage]]:
        fid, dmimg = self._dev.getRawImage()
        return int(fid), dmimg

    def getInferImg(self) -> Tuple[int, Optional[_cx.DMTacImage]]:
        fid, dmimg = self._dev.getInferImage()
        return int(fid), dmimg

    def getDeformation2D(self) -> Tuple[int, Optional[np.ndarray]]:
        fid, flow = self._dev.getDeformation2D()
        return int(fid), flow

    def getShear(self) -> Tuple[int, Optional[np.ndarray]]:
        fid, shear = self._dev.getShear()
        return int(fid), shear

    def getDepth(self) -> Tuple[int, Optional[np.ndarray]]:
        fid, depth = self._dev.getDepth()
        return int(fid), depth

    def getForce(self) -> Tuple[int, Optional[np.ndarray]]:
        fid, force = self._dev.getForce()
        return int(fid), force

    def getDistributeForce(self) -> Tuple[int, Optional[np.ndarray]]:
        fid, dist = self._dev.getDistributeForce()
        return int(fid), dist

    def setBaseFrame(self, img: _cx.DMTacImage) -> None:
        if not isinstance(img, _cx.DMTacImage):
            raise TypeError("setBaseFrame expects dmSDK.DMTacImage")
        ok = bool(self._dev.setBaseFrame(img))
        if not ok:
            raise RuntimeError("setBaseFrame failed")

    def wait_for_new(self, last_id: int, timeout_ms: int = 1000) -> bool:
        return bool(self._dev.waitForNew(int(last_id), int(timeout_ms)))

    def getDevStatus(self) -> int:
        return int(self._dev.getDevStatus())

    def getDevID(self) -> str:
        return str(self._dev.getDevID())

    def getEvents(self, after_seq: Optional[int] = None) -> Tuple[int, List[Dict[str, Any]]]:
        if after_seq is None:
            after_seq = self._event_seq
        newest, evs = self._dev.getEvents(int(after_seq))
        self._event_seq = int(newest)
        return int(newest), list(evs)

    def reset(self) -> None:
        self._dev.reset()

    def disconnect(self) -> None:
        self._dev.disconnect()

    def setMaxFPS(self, max_fps: int) -> None:
        self._dev.setMaxFPS(int(max_fps))

    def getContactArea(self) -> float:
        return float(self._dev.getContactArea())

    def setEnableFlags(
        self,
        enable_raw: bool,
        enable_deformation: bool,
        enable_depth: bool,
        enable_shear: bool,
        enable_force: bool,
    ) -> None:
        self._dev.setEnableFlags(
            bool(enable_raw),
            bool(enable_deformation),
            bool(enable_depth),
            bool(enable_shear),
            bool(enable_force),
        )
        self._enable_raw = bool(enable_raw)
        self._enable_deformation = bool(enable_deformation)
        self._enable_depth = bool(enable_depth)
        self._enable_shear = bool(enable_shear)
        self._enable_force = bool(enable_force)

    def process(
        self,
        img: _cx.DMTacImage,
        enable_depth: bool = True,
        enable_shear: bool = True,
        enable_force: bool = True,
        enable_distforce: bool = True,
    ) -> Tuple[
        Optional[np.ndarray],
        Optional[np.ndarray],
        Optional[np.ndarray],
        Optional[np.ndarray],
        Optional[np.ndarray],
        Optional[np.ndarray],
    ]:
        if not isinstance(img, _cx.DMTacImage):
            raise TypeError("process expects dmSDK.DMTacImage")

        return self._dev.process(img, enable_depth, enable_shear, enable_force, enable_distforce)


from .detect import init_sensor_cache, set_detect_enabled



def listConnectedDevIDs() -> List[Dict[str, Union[int, str]]]:
    return list(_cx.listConnectedDevIDs())
